'use client'

import { useEffect, useState } from 'react'
import { useParams } from 'next/navigation'
import { createClient } from '@/lib/supabase/client'
import Link from 'next/link'
import { ArrowLeft, Mail, Phone } from 'lucide-react'

interface BookingRow {
  id: string
    customer_name: string
      customer_email: string
        customer_phone: string | null
          job_description: string
            status: string
              created_at: string
                dispatch_slot_offered: string | null
                }

                function getInitials(name: string): string {
                  const parts = name.trim().split(' ')
                    if (parts.length === 1) return parts[0].charAt(0).toUpperCase()
                      return (parts[0].charAt(0) + parts[parts.length - 1].charAt(0)).toUpperCase()
                      }

                      function getAvatarColor(email: string): string {
                        const colors = [
                            'bg-yellow-400/20 text-yellow-400',
                                'bg-blue-500/20 text-blue-400',
                                    'bg-green-500/20 text-green-400',
                                        'bg-purple-500/20 text-purple-400',
                                            'bg-orange-500/20 text-orange-400',
                                                'bg-pink-500/20 text-pink-400',
                                                    'bg-teal-500/20 text-teal-400',
                                                        'bg-red-500/20 text-red-400',
                                                          ]
                                                            let hash = 0
                                                              for (let i = 0; i < email.length; i++) hash = (hash * 31 + email.charCodeAt(i)) & 0xffffffff
                                                                return colors[Math.abs(hash) % colors.length]
                                                                }

                                                                const STATUS_CLASSES: Record<string, string> = {
                                                                  pending: 'bg-white/8 text-white/50 border border-white/10',
                                                                    slot_offered: 'bg-yellow-400/15 text-yellow-400 border border-yellow-400/25',
                                                                      booked: 'bg-green-500/15 text-green-400 border border-green-500/25',
                                                                        declined: 'bg-red-500/15 text-red-400 border border-red-500/25',
                                                                          cancelled: 'bg-red-500/15 text-red-400 border border-red-500/25',
                                                                          }

                                                                          function formatDateTime(iso: string): string {
                                                                            const d = new Date(iso)
                                                                              return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' }) +
                                                                                  ' at ' + d.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' })
                                                                                  }

                                                                                  function formatDate(iso: string): string {
                                                                                    return new Date(iso).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })
                                                                                    }

                                                                                    export default function CustomerDetailPage() {
                                                                                      const params = useParams()
                                                                                        const customerId = params.customerId as string
                                                                                          const decodedEmail = decodeURIComponent(customerId)

                                                                                            const [rows, setRows] = useState<BookingRow[]>([])
                                                                                              const [loading, setLoading] = useState(true)
                                                                                                const [error, setError] = useState<string | null>(null)

                                                                                                  useEffect(() => {
                                                                                                      async function fetchData() {
                                                                                                            setLoading(true)
                                                                                                                  setError(null)
                                                                                                                        try {
                                                                                                                                const supabase = createClient()
                                                                                                                                        const { data: { user } } = await supabase.auth.getUser()
                                                                                                                                                if (!user) { setError('Not signed in'); setLoading(false); return }
                                                                                                                                                        const { data, error: dbErr } = await supabase
                                                                                                                                                                  .from('booking_requests')
                                                                                                                                                                            .select('id, customer_name, customer_email, customer_phone, job_description, status, created_at, dispatch_slot_offered')
                                                                                                                                                                                      .eq('pro_id', user.id)
                                                                                                                                                                                                .eq('customer_email', decodedEmail)
                                                                                                                                                                                                          .order('created_at', { ascending: false })
                                                                                                                                                                                                                  if (dbErr) { setError(dbErr.message); setLoading(false); return }
                                                                                                                                                                                                                          setRows(data || [])
                                                                                                                                                                                                                                } catch (e: unknown) {
                                                                                                                                                                                                                                        setError(e instanceof Error ? e.message : 'Failed to load')
                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                    setLoading(false)
                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                            fetchData()
                                                                                                                                                                                                                                                              }, [decodedEmail])
                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                const customer = rows[0]
                                                                                                                                                                                                                                                                  const totalRequests = rows.length
                                                                                                                                                                                                                                                                    const bookedCount = rows.filter(r => r.status === 'booked').length
                                                                                                                                                                                                                                                                      const firstDate = rows.length > 0 ? rows[rows.length - 1].created_at : null
                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                        return (
                                                                                                                                                                                                                                                                            <div className="min-h-screen bg-[#07090D] px-4 py-8 lg:px-8">
                                                                                                                                                                                                                                                                                  <div className="max-w-2xl mx-auto">
                                                                                                                                                                                                                                                                                          <Link href="/customers" className="inline-flex items-center gap-2 text-white/40 hover:text-white/70 text-sm mb-6 transition-colors">
                                                                                                                                                                                                                                                                                                    <ArrowLeft size={16} />
                                                                                                                                                                                                                                                                                                              Back to Customers
                                                                                                                                                                                                                                                                                                                      </Link>
                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                              {loading && (
                                                                                                                                                                                                                                                                                                                                        <div className="bg-[#0B0F17] border border-white/6 rounded-xl p-6 animate-pulse">
                                                                                                                                                                                                                                                                                                                                                    <div className="flex items-center gap-4 mb-6">
                                                                                                                                                                                                                                                                                                                                                                  <div className="w-16 h-16 rounded-full bg-white/8 flex-shrink-0" />
                                                                                                                                                                                                                                                                                                                                                                                <div>
                                                                                                                                                                                                                                                                                                                                                                                                <div className="h-5 w-40 bg-white/8 rounded mb-2" />
                                                                                                                                                                                                                                                                                                                                                                                                                <div className="h-3 w-56 bg-white/5 rounded" />
                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                            )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {!loading && error && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div className="bg-red-500/10 border border-red-500/20 rounded-xl p-4 text-red-400 text-sm">{error}</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {!loading && !error && customer && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div className="bg-[#0B0F17] border border-white/6 rounded-xl p-6 mb-6">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div className="flex items-center gap-4 mb-5">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div className={`w-16 h-16 rounded-full flex items-center justify-center flex-shrink-0 font-mono text-xl font-medium ${getAvatarColor(customer.customer_email)}`}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {getInitials(customer.customer_name)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <h1 className="font-mono text-xl text-white font-medium">{customer.customer_name}</h1>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <a href={`mailto:${customer.customer_email}`} className="flex items-center gap-1.5 text-white/40 hover:text-white/70 text-sm transition-colors mt-0.5">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <Mail size={12} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {customer.customer_email}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </a>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {customer.customer_phone
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ? <a href={`tel:${customer.customer_phone}`} className="flex items-center gap-1.5 text-white/40 hover:text-white/70 text-sm transition-colors mt-0.5">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <Phone size={12} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {customer.customer_phone}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </a>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  : <p className="text-white/20 text-sm italic mt-0.5">No phone on file</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div className="grid grid-cols-3 gap-3 border-t border-white/6 pt-4">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <p className="text-white/30 text-xs mb-0.5">First contact</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <p className="font-mono text-sm text-white">{firstDate ? formatDate(firstDate) : '-'}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <p className="text-white/30 text-xs mb-0.5">Total requests</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <p className="font-mono text-sm text-white">{totalRequests}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <p className="text-white/30 text-xs mb-0.5">Bookings confirmed</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <p className="font-mono text-sm text-white">{bookedCount}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <h2 className="font-mono text-sm uppercase tracking-widest text-white/40 mb-3">Booking History</h2>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {rows.length === 0 ? (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <p className="text-white/30 text-sm text-center py-8">No booking history found.</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ) : (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div className="flex flex-col gap-3">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {rows.map(row => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const statusClass = STATUS_CLASSES[row.status] ?? STATUS_CLASSES.pending
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div key={row.id} className="bg-[#0B0F17] border border-white/6 rounded-xl p-4">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div className="flex items-start justify-between gap-3 mb-2">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <span className="text-white/30 text-xs">{formatDateTime(row.created_at)}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <span className={`font-mono text-[10px] uppercase tracking-widest px-2 py-0.5 rounded-full flex-shrink-0 ${statusClass}`}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {row.status.replace(/_/g, ' ')}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <p className="text-white text-sm">{row.job_description}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {row.dispatch_slot_offered && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <p className="text-white/30 text-xs mt-1.5">Offered slot: {formatDateTime(row.dispatch_slot_offered)}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            })}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {!loading && !error && !customer && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div className="bg-[#0B0F17] border border-white/6 rounded-xl p-8 text-center">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <p className="text-white/30 text-sm">Customer not found.</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
